/// <summary>
/// The <c>METBulkWFWorkItemManagerMainService</c> class for approved/ reject/ delete free text invoice batch job.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
public class METBulkWFWorkItemManagerMainService extends SysOperationServiceBase
{
    int                         numberOfThreads;
    BatchGroupId                batchGroupId;
    Query                       query;
    WorkflowComment             workflowComment;
    WorkflowWorkItemActionType  actionType;
    UserId                      userId;

}

Method.Source:
/// <summary>
/// Executes the batch job with the provided contract.
/// </summary>
/// <param name="_contract">The contract containing the parameters for the batch job.</param>
public void execute(METBulkWFWorkItemManagerMainContract _contract)
{
    numberOfThreads = _contract.parmNoOfThreads();
    query           = _contract.getQuery();
    workflowComment = _contract.parmWorkFlowComment();
    actionType      = _contract.parmWorkflowActionType();
    userId          = _contract.parmUserId();

    this.splitRecordsPerTask();
}

/// <summary>
/// Splits the records based on the number of threads.
/// </summary>
public void splitRecordsPerTask()
{
    QueryRun                        queryRun;
    int                             i;
    METTmpStagingRecords            tmpStagingRecords;
    int                             numOfRecForLastThread;
    int                             startIdx;
    int                             endIdx;
    BatchHeader                     batchHeader;
    RefRecId                        startIndex,
                                    endIndex;
    int                             numOfRecForThread;
    Container                       queryData;

    queryRun  = new QueryRun(query);
    queryData = queryRun.pack();

    //Count of all records in result is 0.
    if (SysQuery::countTotal(queryRun) == 0)
    {
        info("@MET:METFTINoValidRecordsExist");
        return;
    }

    // Start insert
    tmpStagingRecords = METBulkWFFreeTextInvoiceHelper::insertTempStagingTable(queryData);

    select count(RecId) from tmpStagingRecords;

    if (tmpStagingRecords.RecId < numberOfThreads)
    {
        numberOfThreads = int642int(tmpStagingRecords.RecId);
    }

    numOfRecForThread     = real2int(tmpStagingRecords.RecId/numberOfThreads);
    numOfRecForLastThread = int642int(tmpStagingRecords.RecId) - (numOfRecForThread * numberOfThreads);

    batchHeader = BatchHeader::getCurrentBatchHeader();

    if (batchHeader == null)
    {
        batchHeader = BatchHeader::construct();
    }

    batchGroupId = BatchHeader::getCurrentBatchTask().GroupId;

    startIdx = 1;
    endIdx   = numOfRecForThread;

    //Batch budling based on the number of threads.
    for (i = 1; i <= numberOfThreads; i++)
    {
        startIndex  = METBulkWFFreeTextInvoiceHelper::getIndex(tmpStagingRecords, startIdx);
        endIndex    = METBulkWFFreeTextInvoiceHelper::getIndex(tmpStagingRecords, endIdx);

        if (i == numberOfThreads)
        {
            endIndex = METBulkWFFreeTextInvoiceHelper::getIndex(tmpStagingRecords, endIdx + numOfRecForLastThread);
        }

        this.createSubJobs(batchHeader, startIndex, endIndex);

        startIdx = startIdx + numOfRecForThread;
        endIdx   = endIdx + numOfRecForThread;
    }

    batchHeader.save();
}

/// <summary>
/// Creates the subjobs based on the number of threads.
/// </summary>
/// <param name = "_batchHeader">The batch header containing the batch job information.</param>
/// <param name = "_startRecId">The starting record ID for the subjob.</param>
/// <param name = "_endRecId">The ending record ID for the subjob.</param>
public void createSubJobs(BatchHeader _batchHeader, RefRecId _startRecId, RefRecId _endRecId)
{
    METBulkWorkflowWorkItemManagerSubTaskContract   subTaskData;
    METBulkWorkflowWorkItemManagerSubTaskController controller = METBulkWorkflowWorkItemManagerSubTaskController::newFromArgs();
    controller.parmDialogCaption(strFmt("@MET:METFTISubTaskWFCaption", _startRecId, _endRecId));

    subTaskData = controller.getDataContractObject();
    subTaskData.parmStartRefRecId(_startRecId);
    subTaskData.parmEndRefRecId(_endRecId);
    subTaskData.parmWorkFlowComment(workflowComment);
    subTaskData.parmWorkflowActionType(actionType);
    subTaskData.parmUserId(userId);

    controller.batchInfo().parmGroupId(batchGroupId);
    _batchHeader.addRuntimeTask(controller,this.getCurrentBatchTask().RecId);
}
